import React from 'react';
import { SankeyNode } from 'd3-sankey';

interface NumberProps {
  data: SankeyNode<any, any>;
  textColor: string;
  labelSize: number;
}

export const ValueLabel: React.FC<NumberProps> = ({ data, textColor, labelSize }) => {
  let { x0, x1, y1, value } = data;
  const fontSize = labelSize + 'px';

  return (
    <text
      x={(x0 + x1) / 2}
      y={y1 + 20}
      fill={textColor}
      style={{
        alignmentBaseline: 'middle',
        fontSize: fontSize,
        fontWeight: 'bold',
        textAnchor: 'middle',
        pointerEvents: 'none',
        userSelect: 'none',
      }}
    >
      {/*  TODO: remove hardcode */}
      {value} SP
    </text>
  );
};
